import { useState, useEffect } from 'react';
import { api } from '../services/api';
import {
  Search,
  Check,
  X,
  MapPin,
  Truck,
  Package,
  DollarSign,
  Clock,
  ChevronDown,
  ChevronUp,
  CheckCircle,
  XCircle,
  Trash2,
  Edit,
  Mail,
  Phone,
  User,
  Printer,
  Layout,
  List,
  BarChart2,
  Settings,
  LogOut,
  ClipboardList
} from 'lucide-react';

const statusOrder = [
  'Pending',
  'Confirmed',
  'Shipped',
  'Out for Delivery',
  'Delivered',
  'Cancelled'
];

const statusConfig = {
  Pending: { label: 'Abierto', color: 'blue' },
  Confirmed: { label: 'En preparación', color: 'yellow' },
  Shipped: { label: 'Listo', color: 'green' },
  'Out for Delivery': { label: 'En camino', color: 'orange' },
  Delivered: { label: 'Finalizado', color: 'emerald' },
  Cancelled: { label: 'Cancelado', color: 'gray' }
};

const formatDate = (dateString) => {
  if (!dateString) return '';
  const options = { hour: '2-digit', minute: '2-digit' };
  return new Date(dateString).toLocaleTimeString(undefined, options);
};

const Sidebar = () => (
  <aside className="h-full w-64 bg-white border-r border-gray-200 flex flex-col p-4 space-y-6">
    <div className="flex items-center space-x-3">
      <ClipboardList className="h-6 w-6 text-blue-600" />
      <h1 className="text-xl font-bold text-gray-800">Central Abastos</h1>
    </div>
    <nav className="flex-1 flex-col space-y-2">
      <a href="#" className="flex items-center px-3 py-2 rounded-md text-sm font-medium hover:bg-gray-50">
        <List className="h-4 w-4 text-gray-500 mr-3" />
        Órdenes
      </a>
      <a href="#" className="flex items-center px-3 py-2 rounded-md text-sm font-medium hover:bg-gray-50">
        <BarChart2 className="h-4 w-4 text-gray-500 mr-3" />
        Dashboard
      </a>
      <a href="#" className="flex items-center px-3 py-2 rounded-md text-sm font-medium hover:bg-gray-50">
        <Settings className="h-4 w-4 text-gray-500 mr-3" />
        Configuración
      </a>
      <a href="#" className="flex items-center px-3 py-2 rounded-md text-sm font-medium hover:bg-gray-50">
        <LogOut className="h-4 w-4 text-gray-500 mr-3" />
        Cerrar sesión
      </a>
    </nav>
  </aside>
);

const Orders = () => {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Fetch orders
  useEffect(() => {
    const fetchOrders = async () => {
      try {
        setLoading(true);
        const res = await api.get('/orders');
        setOrders(Array.isArray(res.data) ? res.data : []);
        setError(null);
      } catch (err) {
        console.error('Failed to fetch orders:', err);
        setError('No se pudieron cargar las órdenes');
      } finally {
        setLoading(false);
      }
    };
    fetchOrders();
  }, []);

  // Filter and search
  const filteredOrders = orders.filter(
    (order) =>
      (order.id?.toString().includes(searchTerm) ||
        order.customerName?.toLowerCase().includes(searchTerm.toLowerCase())) &&
      (!searchTerm || true)
  );

  // Group by status
  const grouped = {};
  filteredOrders.forEach((order) => {
    const status = order.status || 'Pending';
    if (!grouped[status]) {
      grouped[status] = [];
    }
    grouped[status].push(order);
  });

  // Render status sections
  const renderStatusSections = () => {
    return statusOrder.map((status) => {
      const items = grouped[status] || [];
      const config = statusConfig[status] || { label: status, color: 'gray' };
      return (
        <div key={status} className="mb-6">
          <div className="flex items-center justify-between mb-2">
            <h2 className="text-lg font-semibold text-gray-800">{config.label}</h2>
            <span className={`px-2.5 py-0.5 rounded-full text-xs font-medium bg-${config.color}-100 text-${color}-800`}>
              {items.length}
            </span>
          </div>
          {items.length === 0 ? (
            <p className="text-sm text-gray-500">No hay órdenes en este estado</p>
          ) : (
            <div className="space-y-3">
              {items.map((order) => (
                <div
                  key={order.id}
                  onClick={() => {
                    // If order doesn't have items, fetch details
                    if (!order.items || order.items.length === 0) {
                      api
                        .get(`/orders/${order.id}`)
                        .then((res) => {
                          const detailed = res.data;
                          setSelectedOrder(detailed);
                        })
                        .catch((err) => console.error(err));
                    } else {
                      setSelectedOrder(order);
                    }
                  }}
                  className="flex items-start gap-3 p-4 bg-white rounded-lg border border-gray-200 hover:shadow-md cursor-pointer transition-shadow"
                >
                  {/* Status badge */}
                  <span
                    className={`px-2 py-0.5 rounded text-xs font-medium bg=${config.color}-100 text=${config.color}-800`}
                  >
                    {config.label}
                  </span>
                  <div className="flex-1 space-y-1">
                    <p className="text-sm font-medium">Orden #{order.id}</p>
                    <p className="text-sm text-gray-500">
                      {order.customerName || 'Cliente desconocido'}
                    </p>
                    <p className="text-sm text-gray-500">
                      {formatDate(order.date)}
                    </p>
                    <p className="text-sm font-semibold">
                      Total: ${Number(order.totalAmount || 0).toFixed(2)}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    });
  };

  // Order detail panel
  const renderOrderDetail = () => {
    if (!selectedOrder) return null;
    const config =
      statusConfig[selectedOrder.status] || statusConfig.Pending;
    const items = selectedOrder.items || [];
    const subtotal = items.reduce(
      (sum, item) => sum + (item.unitPrice * item.quantity),
      0
    );

    return (
      <div className="w-full space-y-4">
        {/* Left: Order Info & Actions */}
        <div className="w-full flex-1 space-y-4">
          <div className="bg-white rounded-lg border border-gray-200 p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <span
                  className={`px-2 py-0.5 rounded-full text-xs font-medium bg=${config.color}-100 text=${config.color}-800`}
                >
                  {config.label}
                </span>
                <span className="text-sm font-medium">{config.label}</span>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => {
                    // Example action: mark as ready
                    alert('Marcar como listo (funcionalidad pendiente)');
                  }}
                  className="px-3 py-1.5 text-xs font-medium bg-green-100 text-green-800 rounded hover:bg-green-200 transition-colors"
                >
                  Listo
                </button>
                <button
                  onClick={() => {
                    // Example action: cancel
                    if (
                      window.confirm(
                        '¿Está seguro de cancelar esta orden? Esta acción no se puede deshacer.'
                      )
                    ) {
                      alert('Cancelar orden (funcionalidad pendiente)');
                    }
                  }}
                  className="px-3 py-1.5 text-xs font-medium bg-red-100 text-red-800 rounded hover:bg-red-200 transition-colors"
                >
                  Cancelar
                </button>
              </div>
            </div>

            {/* Customer & Contact */}
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <Phone className="h-4 w-4 text-gray-500" />
                <div>
                  <p className="text-sm font-medium">
                    Cliente: {selectedOrder.customerName || 'N/A'}
                  </p>
                  <p className="text-sm text-gray-500">
                    Tel: {selectedOrder.customerPhone || 'No proporcionado'}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <MapPin className="h-4 w-4 text-gray-500" />
                <div>
                  <p className="text-sm font-medium">Dirección de entrega</p>
                  <p className="text-sm text-gray-500 line-clamp-2">
                    {selectedOrder.deliveryAddress ||
                      'Dirección no disponible'}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <Mail className="h-4 w-4 text-gray-500" />
                <div>
                  <p className="text-sm font-medium">Correo</p>
                  <p className="text-sm text-gray-500">
                    {selectedOrder.customerEmail || 'No proporcionado'}
                  </p>
                </div>
              </div>
            </div>

            {/* Items List */}
            <div className="border-t border-gray-200 pt-4">
              <p className="mb-2 font-semibold text-sm">Productos</p>
              <div className="space-y-2">
                {items.length > 0 ? (
                  items.map((item, index) => (
                    <div
                      key={index}
                      className="flex justify-between py-2 border-t border-gray-200 first:border-t-0"
                    >
                      <div className="flex-1">
                        <p className="text-sm font-medium">
                          {item.productName || 'Producto'}
                        </p>
                        <p className="text-xs text-gray-500">
                          Cantidad: {item.quantity}
                        </p>
                      </div>
                      <div className="text-right text-sm font-medium">
                        ${(item.unitPrice * item.quantity).toFixed(2)}
                      </div>
                    </div>
                  ))
                ) : (
                  <p className="text-sm text-gray-500 px-2 py-2">
                    No hay artículos en esta orden
                  </p>
                )}
              </div>
            </div>

            {/* Totals */}
            <div className="mt-4 pt-4 border-t border-gray-200">
              <div className="flex justify-between text-sm font-medium">
                <span>Subtotal:</span>
                <span>${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm font-medium mt-1">
                <span>Total:</span>
                <span>${Number(selectedOrder.totalAmount || 0).toFixed(2)}</span>
              </div>
            </div>
          </div>

          {/* Notes */}
          {selectedOrder.notes && (
            <div className="mt-4 bg-white rounded-lg border border-gray-200 p-4">
              <p className="font-semibold mb-2">Notas</p>
              <p className="text-sm text-gray-600 whitespace-pre-line">
                {selectedOrder.notes}
              </p>
            </div>
          )}
        </div>

        {/* Right: Summary / Map Preview (placeholder) */}
        <div className="w-full sm:w-64 bg-white rounded-lg border border-gray-200 p-4 space-y-4">
          <div className="space-y-2">
            <p className="font-semibold">Resumen</p>
            <div className="space-y-1 text-sm">
              <div className="flex justify-between">
                <span>Estado:</span>
                <span className={`px-2 py-0.5 rounded-full text-xs font-medium bg=${config.color}-100 text=${config.color}-800`}>
                  {config.label}
                </span>
              </div>
              <div className="flex justify-between">
                <span>Artículos:</span>
                <span>{items.length}</span>
              </div>
              <div className="flex justify-between">
                <span>Peso estimado:</span>
                <span>- kg</span>
              </div>
            </div>
          </div>
          <div className="border-t pt-4">
            <p className="font-semibold mb-2">Acciones rápidas</p>
            <div className="space-y-2">
              <button
                onClick={() => {
                  // Example: print ticket
                  window.print();
                }}
                className="w-full flex items-center justify-start gap-2 px-3 py-2 text-sm font-medium bg-blue-50 hover:bg-blue-100 rounded border border-blue-200"
              >
                <Printer className="h-4 w-4 text-blue-600" />
                <span>Imprimir ticket</span>
              </button>
              <button
                onClick={() => {
                  // Example: notify customer
                  alert('Notificar al cliente (pendiente)');
                }}
                className="w-full flex items-center justify-start gap-2 px-3 py-2 text-sm font-medium bg-green-50 hover:bg-green-100 rounded border border-green-200"
              >
                <Phone className="h-4 w-4 text-green-600" />
                <span>Notificar cliente</span>
              </button>
              <button
                onClick={() => {
                  // Example: assign driver
                  alert('Asignar conductor (pendiente)');
                }}
                className="w-full flex items-center justify-start gap-2 px-3 py-2 text-sm font-md bg-indigo-50 hover:bg-indigo-100 rounded border border-indigo-200"
              >
                <User className="h-4 w-4 text-indigo-600" />
                <span>Asignar conductor</span>
              </button>
            </div>
          </div>
        </div>

        {/* Back button */}
        <div className="mt-4 flex justify-end">
          <button
            onClick={() => setSelectedOrder(null)}
            className="px-4 py-2 text-sm font-medium bg-gray-100 hover:bg-gray-200 rounded transition-colors"
          >
            ← Volver a la lista
          </button>
        </div>
      </div>
    );
  };

  if (loading) return <div className="flex h-full items-center justify-center">Cargando...</div>;
  if (error)
    return (
      <div className="flex h-full items-center justify-center text-red-500">
        {error}
      </div>
    );

  return (
    <div className="min-h-[calc(100vh-4rem)] flex">
      {/* Sidebar */}
      <Sidebar />

      {/* Main content */}
      <div className="flex-1 flex flex-col">
        {/* Search bar */}
        <div className="px-6 py-4 border-b border-gray-200">
          <div className="flex items-center gap-3">
            <Search className="h-4 w-4 text-gray-500" />
            <input
              type="text"
              placeholder="Buscar por ID o cliente..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="flex-1 min-w-0 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={() => setSearchTerm('')}
              className="px-3 py-2 bg-gray-100 hover:bg-gray-200 rounded transition-colors text-sm"
              disabled={!searchTerm}
            >
              Limpiar
            </button>
          </div>
        </div>

        {/* Orders list */}
        <div className="flex-1 p-6 overflow-y-auto">
          {renderStatusSections()}
        </div>
      </div>

      {/* Order detail panel */}
      <div className="w-72 border-l border-gray-200">
        {renderOrderDetail()}
      </div>
    </div>
  );
};

export default Orders;
